excels.excel:

EXPORT WITH SHEET="客户信用额度分析", HEADER=true,
    MAPPING={"a":"客户名称","b":"信用额度","c":"已用额度","d":"可用额度","e":"额度使用率","f":"信用状态"},
    FORMAT={"b":"#,##0.00","c":"#,##0.00","d":"#,##0.00","e":"0.00%"},
    FORMULAS={
        D2:'B2-C2',E2:'C2/B2',
        D3:'B3-C3',E3:'C3/B3',
        D4:'B4-C4',E4:'C4/B4',
        D5:'B5-C5',E5:'C5/B5',
        D6:'B6-C6',E6:'C6/B6',
        B7:'SUM(B2:B6)',C7:'SUM(C2:C6)',D7:'B7-C7',E7:'C7/B7'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        E4:{color:red,bold:true}
    }
